import{_ as n,o as r,c as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/schueler/verwaltung-hilfe.png",l="/bilder/schueler/verwaltung-hilfe-info.png",c=JSON.parse('{"title":"Hilfefunktionen und Programminformationen aufrufen","description":"","frontmatter":{"title":"Hilfefunktionen und Programminformationen aufrufen","source_pageid":405,"source_revision":3745},"headers":[],"relativePath":"schild3/schueler/hilfe-verwaltung.md","filePath":"schild3/schueler/hilfe-verwaltung.md"}'),o={name:"schild3/schueler/hilfe-verwaltung.md"};function u(s,e,f,m,d,g){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="hilfefunktionen-und-programminformationen-aufrufen" tabindex="-1">Hilfefunktionen und Programminformationen aufrufen <a class="header-anchor" href="#hilfefunktionen-und-programminformationen-aufrufen" aria-label="Permalink to &quot;Hilfefunktionen und Programminformationen aufrufen&quot;">​</a></h1><p>Öffnen Sie Online-Support, Dokumentation, Forum oder Programminformationen über die Hilfe im Bereich Verwaltung.</p><p><a href="/bilder/schueler/verwaltung-hilfe.png"><img src="'+a+'" alt="Über Verwaltung stehen Links zur Hilfe und Informationen zur Verfügung." loading="lazy"></a></p><p><em>Über Verwaltung stehen Links zur Hilfe und Informationen zur Verfügung.</em></p><p>Rufen Sie <em>Verwaltung</em> auf, findet sich in der Kopfzeile das Menü für <em>Hilfe</em>. Hierüber sind folgende Punkte abrufbar:</p><ul><li><strong>Online-Supportprogramm aufrufen</strong> kann verwendet werden, um eine bei SchILD-NRW mitgelieferte Software zu öffnen, mit der sich der Desktop mit der Fachberatung über das Internet teilen lässt.</li><li><strong>Online-Dokumentation aufrufen</strong>, öffnet die im Programm hinterlegte Online-Dokumentation im Standardbrowser.</li><li><strong>Forum SchILD-NRW besuchen</strong> ruft das Forum zu SchILD-NRW und anderer Schulverwaltungssoftware auf. Viele Probleme und deren Lösungen sind dort über die Suchfunktion abrufbar. Sollten Sie weitere Hilfe benötigen, melden Sie sich beim Forum an und stellen Sie die Frage im passenden Unterforum.</li></ul><p><a href="/bilder/schueler/verwaltung-hilfe-info.png"><img src="'+l+'" alt="Das Fenster Info zeigt Informationen zur aktuellen Version, Kompilierungsdatum, Copyright und Hersteller." loading="lazy"></a></p><p><em>Das Fenster Info zeigt Informationen zur aktuellen Version, Kompilierungsdatum, Copyright und Hersteller.</em></p><ul><li><strong>Info</strong> ruft Informationen zu SchILD-NRW auf, so können Sie sehen, welche aktuelle Version mit welchem Kompilierungsdatum genutzt wird. Weiterhin finden sich der Hinweis auf das Copyright und den Hersteller.</li><li><strong>Notenliste zeigen</strong> ruft ein Fenster mit den bei Leistungsdaten zulässigen Noten, Punkten und Kürzeln auf.</li><li><strong>Versionsgeschichte zeigen</strong> ruft die Seite mit der Versionsgeschichte in dieser Dokumentation auf.</li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Hilfe_(Verwaltung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 3745.</p>',11)])])}const p=n(o,[["render",u]]);export{c as __pageData,p as default};
